//! Frozen legacy auto wires from b6fcb895^, full revision
//! cade5b5860aca55e7809b2ff1b758939dd6025c6. They were generated by a detached
//! historical worktree with Zig 0.16.0, ReleaseFast, native x86_64 through
//! encodeFrameWithLevelAndOptionsAlloc(..., .{ .include_content_size = true,
//! .content_checksum = false }). No current resolver produced expected bytes.
//! Capture: 19 levels x (2 CHD hunks + 3 adaptive boundary sizes) = 95 rows.
//! Both 4096-byte CHD hunk wires were identical at every historical level 4..22.
//! At 8193/16384 bytes, levels 4..5 shared one wire and 6..22 another.
const std = @import("std");
const zstd = @import("../../zstd.zig");
const allocator = std.testing.allocator;
const chd_phrase = "CHD signed Zstd level payload abcdefghijklmnopqrstuvwxyz\n";
const chd_input = chd_phrase ** 128;

fn fromHex(comptime hex: []const u8) [hex.len / 2]u8 {
    var bytes: [hex.len / 2]u8 = undefined;
    _ = std.fmt.hexToBytes(&bytes, hex) catch unreachable;
    return bytes;
}

const hunk_0_wire = fromHex(
    "28b52ffd60000f1502009403434844207369676e6564205a737464206c6576656c207061796c6f6164206162636465666768" ++
        "696a6b6c6d6e6f707172737475767778797a0a0100497cee2b28",
);

const hunk_1_wire = fromHex(
    "28b52ffd60000f3d0200a4037475767778797a0a434844207369676e6564205a737464206c6576656c207061796c6f616420" ++
        "6162636465666768696a6b6c6d6e6f707172730002007c71954822725f4101",
);

fn chdHunks() [2][4096]u8 {
    comptime {
        std.debug.assert(chd_phrase.len == 57);
        std.debug.assert(chd_input.len == 7296);
    }
    var hunks: [2][4096]u8 = @splat(@splat(0));
    @memcpy(&hunks[0], chd_input[0..4096]);
    // CHD's partial final hunk: 3200 bytes of remaining payload + 896 zeros.
    @memcpy(hunks[1][0..3200], chd_input[4096..]);
    return hunks;
}

test "Zstd legacy auto CHD hunk wires freeze historical levels 4 through 22" {
    const hunks = chdHunks();
    const frozen = [_][]const u8{ &hunk_0_wire, &hunk_1_wire };
    for (4..23) |wide| {
        const level: c_int = @intCast(wide);
        // Only the actual policy is queried. Expected fields and complete
        // wires below were independently captured from the historical source.
        const native = try zstd.resolveFrameOptionsForLevel(level, .{});
        try std.testing.expectEqual(@as(usize, if (level == 5) 128 else 96), native.match_search_budget);
        try std.testing.expectEqual(level >= 9, native.rep_beam_search);
        try std.testing.expectEqual(zstd.Strategy.auto, native.strategy);
        try std.testing.expect(native.hq == null);
        for (&hunks, frozen) |*input, expected| {
            const actual = try zstd.encodeFrameWithLevelAlloc(allocator, input, level);
            defer allocator.free(actual);
            try std.testing.expectEqualSlices(u8, expected, actual);
            const chd = try zstd.encodeFrameWithLevelAndOptionsAlloc(allocator, input, level, .{
                .include_content_size = true,
                .content_checksum = false,
            });
            defer allocator.free(chd);
            try std.testing.expectEqualSlices(u8, expected, chd);
        }
    }
}

test "Zstd legacy auto 95 state negative control loses a CHD hunk candidate" {
    const hunks = chdHunks();
    const frozen = [_][]const u8{ &hunk_0_wire, &hunk_1_wire };
    var strictly_larger: usize = 0;
    for (4..23) |wide| {
        // The negative policy is explicit. In particular its rep-beam gate
        // is historical and does not depend on the current level resolver.
        for (&hunks, frozen) |*input, expected| {
            const reduced = try zstd.encodeNativeFrameWithOptionsAlloc(allocator, input, .{
                .include_content_size = true,
                .content_checksum = false,
                .match_search_budget = 95,
                .rep_beam_search = wide >= 9,
            });
            defer allocator.free(reduced.frame);
            if (reduced.frame.len > expected.len) strictly_larger += 1;
        }
    }
    // Historical capture: the second hunk grew from 81 to 82 bytes at each
    // level. A constant 95-state auto schedule must not be accepted on parity.
    try std.testing.expect(strictly_larger != 0);
}

const Identity = struct {
    length: usize,
    sha256: [32]u8,
};
const all_8192: Identity = .{ .length = 8048, .sha256 = fromHex("e2c1bc2d6621c2ace18ffa9906ef332c7e67334dff30e7e84857603e194589a2") };
const low_8193: Identity = .{ .length = 6428, .sha256 = fromHex("2bcf230b78834dda641bb2125631f25b458f98ccda651989757698dda7a41ff6") };
const low_16384: Identity = .{ .length = 9678, .sha256 = fromHex("1b5407afed832b907a87d7fe05b5a9d80ddf2e81debbb002dff35f7c2e602dc8") };
const high_8193: Identity = .{ .length = 7262, .sha256 = fromHex("ed70d88b4af8fb026cd68d0b1f103a183f190f9c15d4131634ffa624813cdfee") };
const high_16384: Identity = .{ .length = 10915, .sha256 = fromHex("82adee5e7bd31ed24398f187538ed7fbd26bc98e790b1d530e82b912fbb7e3dc") };

fn adaptiveInput() [16384]u8 {
    var bytes: [16384]u8 = undefined;
    var state: u32 = 0x9e3779b9;
    for (&bytes, 0..) |*byte, i| {
        state = state *% 1664525 +% 1013904223;
        byte.* = @truncate((i / 31) + (state >> 29));
    }
    @memcpy(bytes[8192..12288], bytes[2048..6144]);
    return bytes;
}

test "Zstd legacy auto adaptive 8192 8193 and 16KiB historical wires" {
    const input = adaptiveInput();
    const low = [_]Identity{ all_8192, low_8193, low_16384 };
    const high = [_]Identity{ all_8192, high_8193, high_16384 };
    for (4..23) |wide| {
        const expected = if (wide <= 5) low else high;
        for ([_]usize{ 8192, 8193, 16384 }, expected) |length, identity| {
            const actual = try zstd.encodeFrameWithLevelAlloc(allocator, input[0..length], @intCast(wide));
            defer allocator.free(actual);
            try std.testing.expectEqual(identity.length, actual.len);
            var digest: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(actual, &digest, .{});
            try std.testing.expectEqual(identity.sha256, digest);
        }
    }
}
